<?php $base='../';require_once '../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if($_POST['action']==='add'){db()->prepare('INSERT INTO services(service_name,description,price) VALUES(?,?,?)')->execute([$_POST['name'],$_POST['description'],$_POST['price']]);}elseif($_POST['action']==='toggle'){db()->prepare('UPDATE services SET status=1-status WHERE service_id=?')->execute([(int)$_POST['id']]);}header('Location: services.php');exit;}$rows=db()->query('SELECT * FROM services ORDER BY service_id')->fetchAll();$title='Services';include '../includes/header.php';?><section class="section"><div class="container"><h1>Services</h1><form method="post" class="card p-4 my-4"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="add"><div class="row g-2"><div class="col-md-4"><input class="form-control" name="name" placeholder="Service name" required></div><div class="col-md-5"><input class="form-control" name="description" placeholder="Description" required></div><div class="col-md-2"><input class="form-control" name="price" type="number" step=".01" placeholder="Price"></div><div class="col-md-1"><button class="btn btn-gold">Add</button></div></div></form><div class="table-responsive"><table class="table table-dark"><tr><th>Name</th><th>Description</th><th>Price</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['service_name'])?></td><td><?=e($r['description'])?></td><td><?=number_format($r['price'],2)?></td><td><?=$r['status']?'Active':'Inactive'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['service_id']?>"><button class="btn btn-sm btn-outline-warning">Toggle</button></form></td></tr><?php endforeach;?></table></div></div></section><?php include '../includes/footer.php';?>
